function playMusicBeat() { if (!audioContext || !musicGain || !state.running) { musicTimer = null; return; } const melody = [220, 277.18, 329.63, 277.18, 196, 246.94, 293.66, 246.94]; const now = audioContext.currentTime; const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); oscillator.type = 'triangle'; oscillator.frequency.setValueAtTime(melody[musicStep % melody.length], now); gain.gain.setValueAtTime(.001, now); gain.gain.linearRampToValueAtTime(.12, now + .025); gain.gain.exponentialRampToValueAtTime(.001, now + .22); oscillator.connect(gain); gain.connect(musicGain); oscillator.start(now); oscillator.stop(now + .24); if (musicStep % 4 === 0) { const bass = audioContext.createOscillator(); const bassGain = audioContext.createGain(); bass.type = 'sine'; bass.frequency.setValueAtTime(melody[musicStep % melody.length] / 2, now); bassGain.gain.setValueAtTime(.001, now); bassGain.gain.linearRampToValueAtTime(.16, now + .02); bassGain.gain.exponentialRampToValueAtTime(.001, now + .3); bass.connect(bassGain); bassGain.connect(musicGain); bass.start(now); bass.stop(now + .32); } musicStep += 1; musicTimer = window.setTimeout(playMusicBeat, 260); }
